`timescale 1ns/1ps
// KVJ-B 2026-10-17: lockstep of qkd_attn_service_root against the VERBATIM fixed calendar control of the w16 service
// (qkd_attn_service_root_ref, generated by tools/qwen_attention_native/mk_service_root.py).  Both see the same stimulus
// every edge; every output and every state the rest of the service reads (running, start_qk, start_pv, age, ep,
// layer, ctx, cal, cycles, faults, request_ready, q_ready, busy, active_*) is compared at every negedge.
// LEAD>0: the root runs with PV_LEAD=LEAD and its start_pv / ctx / ep pass LEAD bench relay edges (the die relay chain)
// before the compare; calendars then keep LEAD < PV_START < END_AGE (the root faults the others by design).
// Stimulus: legal and illegal request / q traffic, random calendars (incl. 16-bit wrap and unreachable END/PV ages),
// the production calendars of +CALS=<hex file, 44 hex digits per line> and random asynchronous resets.
// Plusargs: +N=<edges> +SEED=<n> +CALS=<file>.  Prints LOCKSTEP PASS / LOCKSTEP FAIL <mismatches> <first edge>.
module tb_qkd_attn_service_root_lockstep;
 parameter integer LEAD=0,MUT=0;
 reg clk=0,rst_n=0;always #1 clk=~clk;
 reg request_valid=0;reg [15:0] request_epoch=0;reg [5:0] request_layer=0;reg [17:0] request_position=0;
 reg fused=1;reg [175:0] request_calendar=0;reg q_valid=0;reg [4:0] q_beat=0;
 wire rr_ref,qr_ref,busy_ref;wire [15:0] ae_ref;wire [5:0] al_ref;wire [31:0] cyc_ref;
 qkd_attn_service_root_ref u_ref(.clk(clk),.rst_n(rst_n),.request_valid(request_valid),.request_ready(rr_ref),
  .request_epoch(request_epoch),.request_layer(request_layer),.request_position(request_position),
  .fused_program_capability(fused),.request_calendar(request_calendar),.q_valid(q_valid),.q_ready(qr_ref),.q_beat(q_beat),
  .active_epoch(ae_ref),.active_layer(al_ref),.busy(busy_ref),.cycles(cyc_ref));
 wire rr,qr,running,start_qk,start_pv_e,lf,iof;wire [15:0] age,ep;wire [5:0] layer;wire [13:0] ctx;wire [175:0] cal;
 wire [31:0] cyc;
 qkd_attn_service_root #(.PV_LEAD(LEAD),.MUT(MUT)) u_new(.ck(clk),.rst_n(rst_n),.request_valid(request_valid),
  .request_ready(rr),.request_epoch(request_epoch),.request_layer(request_layer),.request_position(request_position),
  .fused_program_capability(fused),.request_calendar(request_calendar),.q_valid(q_valid),.q_beat(q_beat),.q_ready(qr),
  .running(running),.start_qk(start_qk),.start_pv(start_pv_e),.age(age),.ep(ep),.layer(layer),.ctx(ctx),.cal(cal),
  .cycles(cyc),.local_fault(lf),.io_fault(iof));
 // the die relay chain (LEAD registered edges), as in ot_qwen_tp8_attention_native_service_w16_sr
 wire start_pv;
 reg [LEAD:0] rs;reg [13:0] rc[0:LEAD];reg [15:0] re[0:LEAD];
 always @* begin rs[0]=start_pv_e;rc[0]=ctx;re[0]=ep;end
 genvar g;
 generate for(g=1;g<=LEAD;g=g+1)begin:gr
  always @(posedge clk or negedge rst_n)if(!rst_n)rs[g]<=0;else rs[g]<=rs[g-1];
  always @(posedge clk)begin rc[g]<=rc[g-1];re[g]<=re[g-1];end
 end endgenerate
 assign start_pv=rs[LEAD];

 integer N=2000000,SEED=1,errors=0,first=-1,cyc_n=0,ncal=0,tokens=0,pvs=0,resets=0,iofs=0,lfs=0;
 reg [175:0] cals[0:4095];string calf;
 task automatic miss(input string what,input [175:0] a,input [175:0] b);
  errors=errors+1;if(first<0)first=cyc_n;
  if(errors<=10)$display("MISMATCH edge=%0d %s ref=%0h new=%0h",cyc_n,what,a,b);
 endtask
 always @(negedge clk)if(rst_n)begin
  if(rr!==rr_ref)miss("request_ready",rr_ref,rr);
  if(qr!==qr_ref)miss("q_ready",qr_ref,qr);
  if(running!==u_ref.running||running!==busy_ref)miss("running",u_ref.running,running);
  if(start_qk!==u_ref.start_qk)miss("start_qk",u_ref.start_qk,start_qk);
  if(start_pv!==u_ref.start_pv)miss("start_pv",u_ref.start_pv,start_pv);
  if(age!==u_ref.age)miss("age",u_ref.age,age);
  if(ep!==u_ref.ep||ep!==ae_ref)miss("ep",u_ref.ep,ep);
  if(layer!==u_ref.layer||layer!==al_ref)miss("layer",u_ref.layer,layer);
  if(ctx!==u_ref.ctx)miss("ctx",u_ref.ctx,ctx);
  if(cal!==u_ref.cal)miss("cal",u_ref.cal,cal);
  if(cyc!==cyc_ref)miss("cycles",cyc_ref,cyc);
  if(lf!==u_ref.local_fault)miss("local_fault",u_ref.local_fault,lf);
  if(iof!==u_ref.io_fault)miss("io_fault",u_ref.io_fault,iof);
  // what the PV pair captures on its start edge: context_len / epoch after the relay
  if(u_ref.start_pv&&(rc[LEAD]!==u_ref.ctx||re[LEAD]!==u_ref.ep))miss("pv_ctx_ep",{u_ref.ctx,u_ref.ep},{rc[LEAD],re[LEAD]});
  if(u_ref.start_qk)tokens=tokens+1;
  if(u_ref.start_pv)pvs=pvs+1;
 end

 function automatic [15:0] r16(input integer lo,input integer hi);
  r16=16'(lo+($urandom%(hi-lo+1)));
 endfunction
 function automatic [175:0] rand_cal();
  reg [15:0] f[0:10];integer k,m;
  m=$urandom%16;
  if(LEAD>0&&m<5)m=5;    // LEAD runs: END after PV_START (the root faults the rest by design)
  for(k=0;k<11;k=k+1)f[k]=r16(0,400);
  // PV_START = f[7], P0 f[8], P1 f[9], R f[10]
  if(m==0)begin f[7]=16'hffff-r16(0,40);end                      // RESULT/END wrap through 16 bits
  else if(m==1)begin f[7]=r16(0,3);end                           // PV at / below the first edges
  else if(m==2)begin f[8]=r16(0,4);f[9]=r16(0,4);f[10]=r16(0,4);f[7]=r16(0,4);end  // END inside the q window
  else if(m==3)begin f[8]=16'hffff-r16(0,60);end                 // large capture age
  else if(m==4)begin f[7]=16'hffff;end
  if(LEAD>0&&f[7]<=LEAD)f[7]=16'(LEAD+1+($urandom%8));
  rand_cal={f[10],f[9],f[8],f[7],f[6],f[5],f[4],f[3],f[2],f[1],f[0]};
 endfunction

 integer hold_rst=0;
 initial begin
  if(!$value$plusargs("N=%d",N))N=2000000;
  if($value$plusargs("SEED=%d",SEED))void'($urandom(SEED));
  if($value$plusargs("CALS=%s",calf))begin
   integer fd,c;reg [175:0] v;fd=$fopen(calf,"r");
   while(fd!=0&&!$feof(fd)&&ncal<4096)begin c=$fscanf(fd,"%h\n",v);if(c==1)begin cals[ncal]=v;ncal=ncal+1;end end
   if(fd!=0)$fclose(fd);
  end
  $display("LOCKSTEP start LEAD=%0d MUT=%0d N=%0d SEED=%0d production_calendars=%0d",LEAD,MUT,N,SEED,ncal);
  repeat(3)@(posedge clk);#0.5 rst_n=1;
  while(cyc_n<N)begin
   @(posedge clk);#0.25;cyc_n=cyc_n+1;
   // asynchronous reset now and then (sticky faults would otherwise end the useful comparison)
   if(hold_rst>0)begin hold_rst=hold_rst-1;if(hold_rst==0)rst_n=1;end
   else if($urandom%20000==0||((u_ref.io_fault||u_ref.local_fault)&&$urandom%3000==0))begin rst_n=0;hold_rst=1+$urandom%3;resets=resets+1;end
   if(u_ref.io_fault)iofs=iofs+1;if(u_ref.local_fault)lfs=lfs+1;
   // request: legal when ready (sometimes delayed), rarely illegal while busy
   request_valid=(rr_ref&&$urandom%4==0)||($urandom%50000==0);
   if(request_valid)begin
    request_epoch=16'($urandom);request_layer=6'($urandom);
    request_position=($urandom%200==0)?18'(8192+$urandom%300):18'($urandom%8192);
    fused=($urandom%300!=0);
    request_calendar=(ncal>0&&$urandom%3==0)?cals[$urandom%ncal]:rand_cal();
   end else if($urandom%2==0)begin
    request_epoch=16'($urandom);request_layer=6'($urandom);request_position=18'($urandom);request_calendar={6{$urandom}};
   end
   // Q beats on the window, beat = age-1; rare protocol violations
   q_valid=qr_ref^($urandom%20000==0);
   q_beat=($urandom%20000==0)?5'($urandom):5'(u_ref.age-16'd1);   // the age the next edge samples
  end
  if(errors==0)$display("LOCKSTEP PASS edges=%0d tokens=%0d pv_starts=%0d resets=%0d io_fault_edges=%0d local_fault_edges=%0d",
   cyc_n,tokens,pvs,resets,iofs,lfs);
  else $display("LOCKSTEP FAIL %0d mismatches first_edge=%0d tokens=%0d",errors,first,tokens);
  $finish;
 end
endmodule
